INSERT INTO "pedagogical_model_definitions"
  ("id", "code", "version", "status", "schema_version", "name", "description", "metadata", "published_at")
VALUES (gen_random_uuid(), 'CLASSICAL_TRIVIUM', 1, 'PUBLISHED', '1.0.0',
  'Educação Clássica (Trivium)', 'Gramática, lógica e retórica como progressão formativa, com ênfase em línguas clássicas, história ocidental e literatura.',
  '{"subjects":[{"name":"Língua Portuguesa (Gramática & Redação)","color":"#2563EB","icon":"book-open","description":"Estrutura gramatical, ortografia, pontuação, vocabulário e exercícios de cópia e narração.","starterObjectives":["Dominar classes gramaticais fundamentais (substantivo, adjetivo, verbo)","Praticar cópia e ditado diário com pontuação correta","Realizar narração oral de contos e parábolas clássicas"]},{"name":"Latim & Línguas Clássicas","color":"#7C3AED","icon":"scroll","description":"Vocabulário latino básico, declinações e etimologia de raízes ocidentais.","starterObjectives":["Memorizar primeira e segunda declinações latinas","Aprender 50 palavras raízes latinas e seus derivados em português"]},{"name":"Matemática & Aritmética Lógica","color":"#059669","icon":"calculator","description":"Cálculo mental, quatro operações fundamentais, frações e resolução lógica de problemas.","starterObjectives":["Dominar fluência na tabuada de multiplicação (1 ao 10)","Resolver problemas aritméticos de múltiplas etapas com raciocínio lógico"]},{"name":"História Ocidental & Antiga","color":"#D97706","icon":"landmark","description":"Linha do tempo cronológica da Antiguidade, Grécia, Roma e História Sagrada.","starterObjectives":["Construir livro dos séculos com marcos do Mundo Antigo","Compreender a cronologia dos patriarcas, impérios egípcio e romano"]},{"name":"Ciências Naturais & Observação","color":"#0D9488","icon":"microscope","description":"Taxonomia básica, reino vegetal e animal, estações do ano e corpos celestes.","starterObjectives":["Classificar seres vivos por reinos e características observáveis","Identificar as principais constelações e movimentos terrestres"]},{"name":"Literatura Clássica & Poesia","color":"#DB2777","icon":"feather","description":"Leitura em voz alta de grandes obras, fábulas de Esopo e recitação poética.","starterObjectives":["Recitar poemas clássicos de memória com expressividade","Ler e debater fábulas e mitologias formativas"]},{"name":"Musicalização e Artes","color":"#DB2777","icon":"palette","description":"Canto, percepção rítmica, leitura musical, prática instrumental, coral, história da música, desenho, pintura, teatro e fotografia -- incluindo música sacra e congregacional como uma trilha entre várias, não a única.","starterObjectives":["Desenvolver percepção rítmica e leitura musical básica em um instrumento ou na voz","Realizar uma apresentação artística ou musical registrada em portfólio"]},{"name":"Ofícios Práticos","color":"#CA8A04","icon":"scissors","description":"Marcenaria, culinária, costura, jardinagem, elétrica básica, manutenção residencial e artesanato -- formação para o trabalho, o serviço e a responsabilidade cotidiana.","starterObjectives":["Concluir um projeto artesanal ou de marcenaria funcional do início ao fim","Preparar uma refeição completa com segurança alimentar e organização de cozinha"]},{"name":"Tecnologia e Criação","color":"#2563EB","icon":"compass","description":"Programação, eletrônica, robótica, impressão 3D, fabricação digital e produção audiovisual -- criar e resolver problemas com ferramentas do nosso tempo.","starterObjectives":["Construir um projeto simples de programação ou eletrônica funcional","Produzir um material audiovisual ou digital documentando um processo de aprendizagem"]},{"name":"Vocação e Serviço","color":"#0D9488","icon":"hand-heart","description":"Empreendedorismo, projetos comunitários, mentoria profissional e serviço cristão -- vocação como chamado, não apenas escolha de carreira.","starterObjectives":["Planejar e executar um pequeno projeto empreendedor ou comunitário","Participar de uma atividade de serviço com reflexão registrada em portfólio"]},{"name":"Fundamentos da Fé Cristã","color":"#7C3AED","icon":"hand-heart","description":"Narrativa bíblica, doutrinas centrais, oração, vida da igreja e ética cristã aplicada ao cotidiano -- a base comum antes de qualquer aprofundamento denominacional.","starterObjectives":["Recontar os grandes marcos da narrativa bíblica em ordem cronológica","Manter um hábito regular de oração e leitura devocional registrado em diário"]},{"name":"Estudo das Escrituras","color":"#9333EA","icon":"book-open","description":"Leitura bíblica contextualizada, panorama do Antigo e Novo Testamento e introdução a como interpretar um texto com responsabilidade -- distinguindo o que o texto diz do que uma tradição específica interpreta.","starterObjectives":["Elaborar um panorama pessoal dos livros do Antigo e Novo Testamento","Praticar leitura contextualizada de uma passagem, identificando gênero literário e contexto histórico"]},{"name":"Casa, Culinária e Cultivo","color":"#16A34A","icon":"sprout","description":"Segurança alimentar, preparo de refeições, panificação, orçamento doméstico e horta caseira -- da cozinha ao cultivo, mordomia prática do lar.","starterObjectives":["Planejar e preparar um cardápio semanal simples dentro de um orçamento definido","Manter uma horta doméstica simples do plantio à colheita"]},{"name":"Primeiros Socorros e Resiliência","color":"#DC2626","icon":"shield-check","description":"Primeiros socorros, orientação básica ao ar livre e preparo familiar para emergências -- preservar a vida, prevenir riscos e ajudar outras pessoas, sem confronto ou sobrevivencialismo extremo.","starterObjectives":["Demonstrar procedimentos básicos de primeiros socorros para situações comuns do dia a dia","Montar, com a família, um plano simples de preparo para emergências domésticas"]}]}'::jsonb, CURRENT_TIMESTAMP)
ON CONFLICT ("code", "version") DO NOTHING;

INSERT INTO "pedagogical_model_definitions"
  ("id", "code", "version", "status", "schema_version", "name", "description", "metadata", "published_at")
VALUES (gen_random_uuid(), 'CHARLOTTE_MASON', 1, 'PUBLISHED', '1.0.0',
  'Charlotte Mason', 'Livros vivos, narração, estudo da natureza e formação de hábitos e caráter.',
  '{"subjects":[{"name":"Estudo da Natureza (Nature Study)","color":"#16A34A","icon":"leaf","description":"Caderno de natureza com desenhos botânicos, observação ao ar livre e hábitos da fauna.","starterObjectives":["Manter diário de natureza com ilustrações semanais e anotações de campo","Identificar 10 espécies de árvores e pássaros nativos da região"]},{"name":"Livros Vivos (Living Books) & Narração","color":"#9333EA","icon":"book","description":"Educação através de biografias ricas e narração imediata de cada capítulo lido.","starterObjectives":["Realizar narrações orais estruturadas após leituras em voz alta","Leitura de biografias de figuras históricas e cientistas exemplares"]},{"name":"Apreciação de Arte & Música (Picture Study)","color":"#E11D48","icon":"palette","description":"Estudo detalhado de pintores mestres a cada período e escuta atenta de compositores.","starterObjectives":["Estudar obras e técnica de um grande pintor clássico","Apreciação e identificação de temas em peças de música erudita"]},{"name":"Trabalhos Manuais & Habilidades Práticas","color":"#CA8A04","icon":"scissors","description":"Artesanato útil, marcenaria básica, bordado, culinária e cuidados com o lar.","starterObjectives":["Desenvolver e concluir um projeto artesanal funcional","Aprender técnicas de costura básica e manutenção de ferramentas"]},{"name":"Hábito & Formação de Caráter","color":"#0891B2","icon":"heart","description":"Desenvolvimento de virtudes como atenção, ordem, pontualidade e perseverança.","starterObjectives":["Cultivar o hábito da atenção focada em lições breves e intensas","Praticar ordem e zelo na organização dos próprios materiais"]},{"name":"Musicalização e Artes","color":"#DB2777","icon":"palette","description":"Canto, percepção rítmica, leitura musical, prática instrumental, coral, história da música, desenho, pintura, teatro e fotografia -- incluindo música sacra e congregacional como uma trilha entre várias, não a única.","starterObjectives":["Desenvolver percepção rítmica e leitura musical básica em um instrumento ou na voz","Realizar uma apresentação artística ou musical registrada em portfólio"]},{"name":"Ofícios Práticos","color":"#CA8A04","icon":"scissors","description":"Marcenaria, culinária, costura, jardinagem, elétrica básica, manutenção residencial e artesanato -- formação para o trabalho, o serviço e a responsabilidade cotidiana.","starterObjectives":["Concluir um projeto artesanal ou de marcenaria funcional do início ao fim","Preparar uma refeição completa com segurança alimentar e organização de cozinha"]},{"name":"Tecnologia e Criação","color":"#2563EB","icon":"compass","description":"Programação, eletrônica, robótica, impressão 3D, fabricação digital e produção audiovisual -- criar e resolver problemas com ferramentas do nosso tempo.","starterObjectives":["Construir um projeto simples de programação ou eletrônica funcional","Produzir um material audiovisual ou digital documentando um processo de aprendizagem"]},{"name":"Vocação e Serviço","color":"#0D9488","icon":"hand-heart","description":"Empreendedorismo, projetos comunitários, mentoria profissional e serviço cristão -- vocação como chamado, não apenas escolha de carreira.","starterObjectives":["Planejar e executar um pequeno projeto empreendedor ou comunitário","Participar de uma atividade de serviço com reflexão registrada em portfólio"]},{"name":"Fundamentos da Fé Cristã","color":"#7C3AED","icon":"hand-heart","description":"Narrativa bíblica, doutrinas centrais, oração, vida da igreja e ética cristã aplicada ao cotidiano -- a base comum antes de qualquer aprofundamento denominacional.","starterObjectives":["Recontar os grandes marcos da narrativa bíblica em ordem cronológica","Manter um hábito regular de oração e leitura devocional registrado em diário"]},{"name":"Estudo das Escrituras","color":"#9333EA","icon":"book-open","description":"Leitura bíblica contextualizada, panorama do Antigo e Novo Testamento e introdução a como interpretar um texto com responsabilidade -- distinguindo o que o texto diz do que uma tradição específica interpreta.","starterObjectives":["Elaborar um panorama pessoal dos livros do Antigo e Novo Testamento","Praticar leitura contextualizada de uma passagem, identificando gênero literário e contexto histórico"]},{"name":"Casa, Culinária e Cultivo","color":"#16A34A","icon":"sprout","description":"Segurança alimentar, preparo de refeições, panificação, orçamento doméstico e horta caseira -- da cozinha ao cultivo, mordomia prática do lar.","starterObjectives":["Planejar e preparar um cardápio semanal simples dentro de um orçamento definido","Manter uma horta doméstica simples do plantio à colheita"]},{"name":"Primeiros Socorros e Resiliência","color":"#DC2626","icon":"shield-check","description":"Primeiros socorros, orientação básica ao ar livre e preparo familiar para emergências -- preservar a vida, prevenir riscos e ajudar outras pessoas, sem confronto ou sobrevivencialismo extremo.","starterObjectives":["Demonstrar procedimentos básicos de primeiros socorros para situações comuns do dia a dia","Montar, com a família, um plano simples de preparo para emergências domésticas"]}]}'::jsonb, CURRENT_TIMESTAMP)
ON CONFLICT ("code", "version") DO NOTHING;

INSERT INTO "pedagogical_model_definitions"
  ("id", "code", "version", "status", "schema_version", "name", "description", "metadata", "published_at")
VALUES (gen_random_uuid(), 'TRADITIONAL', 1, 'PUBLISHED', '1.0.0',
  'Escolar Tradicional', 'Disciplinas escolares convencionais (Português, Matemática, História, Geografia, Ciências) em sequência estruturada.',
  '{"subjects":[{"name":"Língua Portuguesa","color":"#2563EB","icon":"book","description":"Compreensão de texto, ortografia, redação e gramática normativa.","starterObjectives":["Desenvolver leitura fluente e interpretação de textos de complexidade adequada","Produzir redações estruturadas com início, meio e conclusão"]},{"name":"Matemática","color":"#059669","icon":"calculator","description":"Aritmética, raciocínio quantitativo, medidas e geometria introdutória.","starterObjectives":["Executar operações aritméticas básicas com exatidão e velocidade","Compreender frações, decimais e porcentagens em situações cotidianas"]},{"name":"História","color":"#D97706","icon":"landmark","description":"História do Brasil e marcos fundamentais da civilização.","starterObjectives":["Conhecer os períodos fundamentais da História do Brasil","Identificar causas e impactos das grandes navegações e colonização"]},{"name":"Geografia","color":"#0D9488","icon":"globe","description":"Relevo, clima, cartografia, regiões brasileiras e geopolítica mundial.","starterObjectives":["Localizar continentes, oceanos e estados brasileiros no mapa","Compreender os biomas brasileiros e recursos hídricos"]},{"name":"Ciências","color":"#16A34A","icon":"flask","description":"Biologia, corpo humano, química básica e ecologia.","starterObjectives":["Descrever os principais sistemas do corpo humano e hábitos saudáveis","Compreender o ciclo da água, estados físicos da matéria e cadeias alimentares"]},{"name":"Musicalização e Artes","color":"#DB2777","icon":"palette","description":"Canto, percepção rítmica, leitura musical, prática instrumental, coral, história da música, desenho, pintura, teatro e fotografia -- incluindo música sacra e congregacional como uma trilha entre várias, não a única.","starterObjectives":["Desenvolver percepção rítmica e leitura musical básica em um instrumento ou na voz","Realizar uma apresentação artística ou musical registrada em portfólio"]},{"name":"Ofícios Práticos","color":"#CA8A04","icon":"scissors","description":"Marcenaria, culinária, costura, jardinagem, elétrica básica, manutenção residencial e artesanato -- formação para o trabalho, o serviço e a responsabilidade cotidiana.","starterObjectives":["Concluir um projeto artesanal ou de marcenaria funcional do início ao fim","Preparar uma refeição completa com segurança alimentar e organização de cozinha"]},{"name":"Tecnologia e Criação","color":"#2563EB","icon":"compass","description":"Programação, eletrônica, robótica, impressão 3D, fabricação digital e produção audiovisual -- criar e resolver problemas com ferramentas do nosso tempo.","starterObjectives":["Construir um projeto simples de programação ou eletrônica funcional","Produzir um material audiovisual ou digital documentando um processo de aprendizagem"]},{"name":"Vocação e Serviço","color":"#0D9488","icon":"hand-heart","description":"Empreendedorismo, projetos comunitários, mentoria profissional e serviço cristão -- vocação como chamado, não apenas escolha de carreira.","starterObjectives":["Planejar e executar um pequeno projeto empreendedor ou comunitário","Participar de uma atividade de serviço com reflexão registrada em portfólio"]},{"name":"Fundamentos da Fé Cristã","color":"#7C3AED","icon":"hand-heart","description":"Narrativa bíblica, doutrinas centrais, oração, vida da igreja e ética cristã aplicada ao cotidiano -- a base comum antes de qualquer aprofundamento denominacional.","starterObjectives":["Recontar os grandes marcos da narrativa bíblica em ordem cronológica","Manter um hábito regular de oração e leitura devocional registrado em diário"]},{"name":"Estudo das Escrituras","color":"#9333EA","icon":"book-open","description":"Leitura bíblica contextualizada, panorama do Antigo e Novo Testamento e introdução a como interpretar um texto com responsabilidade -- distinguindo o que o texto diz do que uma tradição específica interpreta.","starterObjectives":["Elaborar um panorama pessoal dos livros do Antigo e Novo Testamento","Praticar leitura contextualizada de uma passagem, identificando gênero literário e contexto histórico"]},{"name":"Casa, Culinária e Cultivo","color":"#16A34A","icon":"sprout","description":"Segurança alimentar, preparo de refeições, panificação, orçamento doméstico e horta caseira -- da cozinha ao cultivo, mordomia prática do lar.","starterObjectives":["Planejar e preparar um cardápio semanal simples dentro de um orçamento definido","Manter uma horta doméstica simples do plantio à colheita"]},{"name":"Primeiros Socorros e Resiliência","color":"#DC2626","icon":"shield-check","description":"Primeiros socorros, orientação básica ao ar livre e preparo familiar para emergências -- preservar a vida, prevenir riscos e ajudar outras pessoas, sem confronto ou sobrevivencialismo extremo.","starterObjectives":["Demonstrar procedimentos básicos de primeiros socorros para situações comuns do dia a dia","Montar, com a família, um plano simples de preparo para emergências domésticas"]}]}'::jsonb, CURRENT_TIMESTAMP)
ON CONFLICT ("code", "version") DO NOTHING;

INSERT INTO "pedagogical_model_definitions"
  ("id", "code", "version", "status", "schema_version", "name", "description", "metadata", "published_at")
VALUES (gen_random_uuid(), 'UNIT_STUDIES', 1, 'PUBLISHED', '1.0.0',
  'Unit Studies', 'Um tema central explorado de forma interdisciplinar, ancorando literatura, matemática, ciências e história.',
  '{"subjects":[{"name":"Estudo Temático Integrado","color":"#7C3AED","icon":"layers","description":"Um tema central (ex: oceanos, Idade Média, corpo humano) explorado de forma interdisciplinar ao longo de semanas.","starterObjectives":["Escolher um tema central e mapear suas conexões com as áreas do conhecimento","Produzir um projeto final que sintetize o aprendizado sobre o tema"]},{"name":"Literatura & Redação Contextualizada","color":"#2563EB","icon":"book-open","description":"Leitura e escrita sempre ancoradas no tema em estudo, em vez de disciplina isolada.","starterObjectives":["Ler ao menos uma obra relacionada ao tema central e produzir uma resenha","Escrever um texto narrativo ou expositivo conectado ao tema em estudo"]},{"name":"Matemática Aplicada ao Tema","color":"#059669","icon":"calculator","description":"Conceitos matemáticos extraídos de situações reais dentro do tema em estudo.","starterObjectives":["Resolver problemas matemáticos construídos a partir do tema central","Registrar e interpretar dados numéricos coletados durante o estudo do tema"]},{"name":"Ciências & Investigação","color":"#0D9488","icon":"microscope","description":"Experimentos e observações científicas conectadas diretamente ao tema central.","starterObjectives":["Conduzir um experimento simples relacionado ao tema em estudo","Registrar hipóteses, observações e conclusões em um caderno de investigação"]},{"name":"História & Cultura do Tema","color":"#D97706","icon":"landmark","description":"Contexto histórico e cultural do tema central, incluindo sua relação com a história sagrada quando pertinente.","starterObjectives":["Situar o tema central em sua linha do tempo histórica e cultural","Apresentar oralmente ou por escrito uma descoberta histórica ligada ao tema"]},{"name":"Musicalização e Artes","color":"#DB2777","icon":"palette","description":"Canto, percepção rítmica, leitura musical, prática instrumental, coral, história da música, desenho, pintura, teatro e fotografia -- incluindo música sacra e congregacional como uma trilha entre várias, não a única.","starterObjectives":["Desenvolver percepção rítmica e leitura musical básica em um instrumento ou na voz","Realizar uma apresentação artística ou musical registrada em portfólio"]},{"name":"Ofícios Práticos","color":"#CA8A04","icon":"scissors","description":"Marcenaria, culinária, costura, jardinagem, elétrica básica, manutenção residencial e artesanato -- formação para o trabalho, o serviço e a responsabilidade cotidiana.","starterObjectives":["Concluir um projeto artesanal ou de marcenaria funcional do início ao fim","Preparar uma refeição completa com segurança alimentar e organização de cozinha"]},{"name":"Tecnologia e Criação","color":"#2563EB","icon":"compass","description":"Programação, eletrônica, robótica, impressão 3D, fabricação digital e produção audiovisual -- criar e resolver problemas com ferramentas do nosso tempo.","starterObjectives":["Construir um projeto simples de programação ou eletrônica funcional","Produzir um material audiovisual ou digital documentando um processo de aprendizagem"]},{"name":"Vocação e Serviço","color":"#0D9488","icon":"hand-heart","description":"Empreendedorismo, projetos comunitários, mentoria profissional e serviço cristão -- vocação como chamado, não apenas escolha de carreira.","starterObjectives":["Planejar e executar um pequeno projeto empreendedor ou comunitário","Participar de uma atividade de serviço com reflexão registrada em portfólio"]},{"name":"Fundamentos da Fé Cristã","color":"#7C3AED","icon":"hand-heart","description":"Narrativa bíblica, doutrinas centrais, oração, vida da igreja e ética cristã aplicada ao cotidiano -- a base comum antes de qualquer aprofundamento denominacional.","starterObjectives":["Recontar os grandes marcos da narrativa bíblica em ordem cronológica","Manter um hábito regular de oração e leitura devocional registrado em diário"]},{"name":"Estudo das Escrituras","color":"#9333EA","icon":"book-open","description":"Leitura bíblica contextualizada, panorama do Antigo e Novo Testamento e introdução a como interpretar um texto com responsabilidade -- distinguindo o que o texto diz do que uma tradição específica interpreta.","starterObjectives":["Elaborar um panorama pessoal dos livros do Antigo e Novo Testamento","Praticar leitura contextualizada de uma passagem, identificando gênero literário e contexto histórico"]},{"name":"Casa, Culinária e Cultivo","color":"#16A34A","icon":"sprout","description":"Segurança alimentar, preparo de refeições, panificação, orçamento doméstico e horta caseira -- da cozinha ao cultivo, mordomia prática do lar.","starterObjectives":["Planejar e preparar um cardápio semanal simples dentro de um orçamento definido","Manter uma horta doméstica simples do plantio à colheita"]},{"name":"Primeiros Socorros e Resiliência","color":"#DC2626","icon":"shield-check","description":"Primeiros socorros, orientação básica ao ar livre e preparo familiar para emergências -- preservar a vida, prevenir riscos e ajudar outras pessoas, sem confronto ou sobrevivencialismo extremo.","starterObjectives":["Demonstrar procedimentos básicos de primeiros socorros para situações comuns do dia a dia","Montar, com a família, um plano simples de preparo para emergências domésticas"]}]}'::jsonb, CURRENT_TIMESTAMP)
ON CONFLICT ("code", "version") DO NOTHING;

INSERT INTO "pedagogical_model_definitions"
  ("id", "code", "version", "status", "schema_version", "name", "description", "metadata", "published_at")
VALUES (gen_random_uuid(), 'MONTESSORI', 1, 'PUBLISHED', '1.0.0',
  'Montessori', 'Vida prática, educação sensorial e materiais concretos, partindo da autonomia e da experiência direta da criança.',
  '{"subjects":[{"name":"Vida Prática","color":"#CA8A04","icon":"scissors","description":"Cuidado pessoal, cuidado do ambiente e coordenação motora através de tarefas reais e autônomas.","starterObjectives":["Executar de forma independente uma sequência de cuidado do ambiente (organizar, limpar, cuidar de plantas)","Demonstrar autonomia crescente em tarefas de cuidado pessoal e do lar"]},{"name":"Educação Sensorial","color":"#DB2777","icon":"palette","description":"Refinamento dos sentidos através de materiais concretos que isolam uma qualidade por vez (cor, forma, textura, peso).","starterObjectives":["Classificar e ordenar materiais sensoriais por uma qualidade específica (tamanho, cor, textura)","Descrever verbalmente diferenças sensoriais percebidas em uma atividade prática"]},{"name":"Linguagem","color":"#2563EB","icon":"book-open","description":"Do vocabulário concreto à escrita e leitura, partindo sempre da experiência sensorial e do nome real das coisas.","starterObjectives":["Expandir vocabulário nomeando objetos e experiências concretas do cotidiano","Progredir da escrita de letras soltas para palavras e frases simples"]},{"name":"Matemática Concreta","color":"#059669","icon":"calculator","description":"Conceitos matemáticos introduzidos por materiais manipuláveis antes da abstração numérica.","starterObjectives":["Representar quantidades e operações básicas usando material concreto (contas, barras, fichas)","Fazer a transição de uma operação concreta para o registro numérico correspondente"]},{"name":"Ciências Cósmicas & Natureza","color":"#16A34A","icon":"leaf","description":"A \"Educação Cósmica\" montessoriana: o lugar do ser humano no universo, na natureza e na criação, através da observação direta.","starterObjectives":["Observar e registrar um fenômeno natural ao longo de um período de tempo","Relacionar uma descoberta científica simples ao seu lugar na criação"]},{"name":"Musicalização e Artes","color":"#DB2777","icon":"palette","description":"Canto, percepção rítmica, leitura musical, prática instrumental, coral, história da música, desenho, pintura, teatro e fotografia -- incluindo música sacra e congregacional como uma trilha entre várias, não a única.","starterObjectives":["Desenvolver percepção rítmica e leitura musical básica em um instrumento ou na voz","Realizar uma apresentação artística ou musical registrada em portfólio"]},{"name":"Ofícios Práticos","color":"#CA8A04","icon":"scissors","description":"Marcenaria, culinária, costura, jardinagem, elétrica básica, manutenção residencial e artesanato -- formação para o trabalho, o serviço e a responsabilidade cotidiana.","starterObjectives":["Concluir um projeto artesanal ou de marcenaria funcional do início ao fim","Preparar uma refeição completa com segurança alimentar e organização de cozinha"]},{"name":"Tecnologia e Criação","color":"#2563EB","icon":"compass","description":"Programação, eletrônica, robótica, impressão 3D, fabricação digital e produção audiovisual -- criar e resolver problemas com ferramentas do nosso tempo.","starterObjectives":["Construir um projeto simples de programação ou eletrônica funcional","Produzir um material audiovisual ou digital documentando um processo de aprendizagem"]},{"name":"Vocação e Serviço","color":"#0D9488","icon":"hand-heart","description":"Empreendedorismo, projetos comunitários, mentoria profissional e serviço cristão -- vocação como chamado, não apenas escolha de carreira.","starterObjectives":["Planejar e executar um pequeno projeto empreendedor ou comunitário","Participar de uma atividade de serviço com reflexão registrada em portfólio"]},{"name":"Fundamentos da Fé Cristã","color":"#7C3AED","icon":"hand-heart","description":"Narrativa bíblica, doutrinas centrais, oração, vida da igreja e ética cristã aplicada ao cotidiano -- a base comum antes de qualquer aprofundamento denominacional.","starterObjectives":["Recontar os grandes marcos da narrativa bíblica em ordem cronológica","Manter um hábito regular de oração e leitura devocional registrado em diário"]},{"name":"Estudo das Escrituras","color":"#9333EA","icon":"book-open","description":"Leitura bíblica contextualizada, panorama do Antigo e Novo Testamento e introdução a como interpretar um texto com responsabilidade -- distinguindo o que o texto diz do que uma tradição específica interpreta.","starterObjectives":["Elaborar um panorama pessoal dos livros do Antigo e Novo Testamento","Praticar leitura contextualizada de uma passagem, identificando gênero literário e contexto histórico"]},{"name":"Casa, Culinária e Cultivo","color":"#16A34A","icon":"sprout","description":"Segurança alimentar, preparo de refeições, panificação, orçamento doméstico e horta caseira -- da cozinha ao cultivo, mordomia prática do lar.","starterObjectives":["Planejar e preparar um cardápio semanal simples dentro de um orçamento definido","Manter uma horta doméstica simples do plantio à colheita"]},{"name":"Primeiros Socorros e Resiliência","color":"#DC2626","icon":"shield-check","description":"Primeiros socorros, orientação básica ao ar livre e preparo familiar para emergências -- preservar a vida, prevenir riscos e ajudar outras pessoas, sem confronto ou sobrevivencialismo extremo.","starterObjectives":["Demonstrar procedimentos básicos de primeiros socorros para situações comuns do dia a dia","Montar, com a família, um plano simples de preparo para emergências domésticas"]}]}'::jsonb, CURRENT_TIMESTAMP)
ON CONFLICT ("code", "version") DO NOTHING;

INSERT INTO "pedagogical_model_definitions"
  ("id", "code", "version", "status", "schema_version", "name", "description", "metadata", "published_at")
VALUES (gen_random_uuid(), 'PROJECT_BASED', 1, 'PUBLISHED', '1.0.0',
  'Aprendizagem Baseada em Projetos', 'Um projeto real e significativo conduz o aprendizado, do planejamento à entrega final.',
  '{"subjects":[{"name":"Projeto Integrador","color":"#7C3AED","icon":"lightbulb","description":"Um projeto real e significativo conduz o aprendizado, do planejamento à entrega final.","starterObjectives":["Definir um problema real ou pergunta motivadora para o projeto","Planejar etapas, prazos e critérios de sucesso do projeto"]},{"name":"Pesquisa & Investigação","color":"#2563EB","icon":"search","description":"Habilidades de buscar, avaliar e organizar informação relevante para o projeto em andamento.","starterObjectives":["Reunir e organizar fontes confiáveis relacionadas ao problema do projeto","Sintetizar achados de pesquisa em um resumo estruturado"]},{"name":"Comunicação & Apresentação","color":"#DB2777","icon":"sparkles","description":"Comunicar o processo e os resultados do projeto de forma clara, oral e escrita.","starterObjectives":["Preparar e realizar uma apresentação estruturada do projeto","Produzir um registro escrito ou visual documentando o processo do projeto"]},{"name":"Matemática Aplicada","color":"#059669","icon":"calculator","description":"Conceitos matemáticos necessários para resolver os desafios concretos do projeto.","starterObjectives":["Aplicar cálculos ou medidas necessárias para a execução do projeto","Interpretar dados quantitativos coletados durante o projeto"]},{"name":"Ciências Aplicadas","color":"#0D9488","icon":"microscope","description":"Conceitos científicos investigados na medida em que o projeto os exige.","starterObjectives":["Identificar e testar um princípio científico relevante para o projeto","Registrar resultados de testes ou experimentos ligados ao projeto"]},{"name":"Musicalização e Artes","color":"#DB2777","icon":"palette","description":"Canto, percepção rítmica, leitura musical, prática instrumental, coral, história da música, desenho, pintura, teatro e fotografia -- incluindo música sacra e congregacional como uma trilha entre várias, não a única.","starterObjectives":["Desenvolver percepção rítmica e leitura musical básica em um instrumento ou na voz","Realizar uma apresentação artística ou musical registrada em portfólio"]},{"name":"Ofícios Práticos","color":"#CA8A04","icon":"scissors","description":"Marcenaria, culinária, costura, jardinagem, elétrica básica, manutenção residencial e artesanato -- formação para o trabalho, o serviço e a responsabilidade cotidiana.","starterObjectives":["Concluir um projeto artesanal ou de marcenaria funcional do início ao fim","Preparar uma refeição completa com segurança alimentar e organização de cozinha"]},{"name":"Tecnologia e Criação","color":"#2563EB","icon":"compass","description":"Programação, eletrônica, robótica, impressão 3D, fabricação digital e produção audiovisual -- criar e resolver problemas com ferramentas do nosso tempo.","starterObjectives":["Construir um projeto simples de programação ou eletrônica funcional","Produzir um material audiovisual ou digital documentando um processo de aprendizagem"]},{"name":"Vocação e Serviço","color":"#0D9488","icon":"hand-heart","description":"Empreendedorismo, projetos comunitários, mentoria profissional e serviço cristão -- vocação como chamado, não apenas escolha de carreira.","starterObjectives":["Planejar e executar um pequeno projeto empreendedor ou comunitário","Participar de uma atividade de serviço com reflexão registrada em portfólio"]},{"name":"Fundamentos da Fé Cristã","color":"#7C3AED","icon":"hand-heart","description":"Narrativa bíblica, doutrinas centrais, oração, vida da igreja e ética cristã aplicada ao cotidiano -- a base comum antes de qualquer aprofundamento denominacional.","starterObjectives":["Recontar os grandes marcos da narrativa bíblica em ordem cronológica","Manter um hábito regular de oração e leitura devocional registrado em diário"]},{"name":"Estudo das Escrituras","color":"#9333EA","icon":"book-open","description":"Leitura bíblica contextualizada, panorama do Antigo e Novo Testamento e introdução a como interpretar um texto com responsabilidade -- distinguindo o que o texto diz do que uma tradição específica interpreta.","starterObjectives":["Elaborar um panorama pessoal dos livros do Antigo e Novo Testamento","Praticar leitura contextualizada de uma passagem, identificando gênero literário e contexto histórico"]},{"name":"Casa, Culinária e Cultivo","color":"#16A34A","icon":"sprout","description":"Segurança alimentar, preparo de refeições, panificação, orçamento doméstico e horta caseira -- da cozinha ao cultivo, mordomia prática do lar.","starterObjectives":["Planejar e preparar um cardápio semanal simples dentro de um orçamento definido","Manter uma horta doméstica simples do plantio à colheita"]},{"name":"Primeiros Socorros e Resiliência","color":"#DC2626","icon":"shield-check","description":"Primeiros socorros, orientação básica ao ar livre e preparo familiar para emergências -- preservar a vida, prevenir riscos e ajudar outras pessoas, sem confronto ou sobrevivencialismo extremo.","starterObjectives":["Demonstrar procedimentos básicos de primeiros socorros para situações comuns do dia a dia","Montar, com a família, um plano simples de preparo para emergências domésticas"]}]}'::jsonb, CURRENT_TIMESTAMP)
