INSERT INTO "pedagogical_model_definitions"
  ("id", "code", "version", "status", "schema_version", "name", "description", "metadata", "published_at")
VALUES (gen_random_uuid(), 'GUIDED_UNSCHOOLING', 1, 'PUBLISHED', '1.0.0',
  'Unschooling Guiado', 'Interesses do aluno como eixo do aprendizado, com mediação e acompanhamento ativo dos pais.',
  '{"subjects":[{"name":"Interesses Dirigidos pelo Aluno","color":"#DB2777","icon":"sparkles","description":"Aprofundamento em áreas de curiosidade genuína do aluno, com mediação e acompanhamento dos pais.","starterObjectives":["Escolher um interesse pessoal e definir um objetivo de aprofundamento com apoio dos pais","Registrar em portfólio o progresso e as descobertas sobre o interesse escolhido"]},{"name":"Leitura Livre & Literatura","color":"#2563EB","icon":"book-open","description":"Leitura ampla e autoescolhida, com espaço para conversa e reflexão sobre o que foi lido.","starterObjectives":["Manter um registro pessoal das leituras realizadas no período","Compartilhar oralmente ou por escrito reflexões sobre uma leitura significativa"]},{"name":"Matemática Funcional","color":"#059669","icon":"calculator","description":"Matemática enraizada em situações reais e nos interesses do aluno, não em uma sequência fixa de exercícios.","starterObjectives":["Resolver um problema matemático real surgido de um interesse ou atividade pessoal","Demonstrar fluência crescente em operações básicas através de uso prático"]},{"name":"Exploração Científica","color":"#0D9488","icon":"microscope","description":"Curiosidade científica guiada por perguntas do próprio aluno, com experimentação livre e mediada.","starterObjectives":["Formular uma pergunta científica própria e investigá-la de forma simples","Registrar uma observação ou experimento motivado por curiosidade pessoal"]},{"name":"Habilidades para a Vida","color":"#CA8A04","icon":"scissors","description":"Competências práticas do cotidiano aprendidas por necessidade e interesse real.","starterObjectives":["Aprender uma habilidade prática nova a partir de uma necessidade real identificada","Demonstrar autonomia crescente em uma tarefa do cotidiano familiar"]},{"name":"Musicalização e Artes","color":"#DB2777","icon":"palette","description":"Canto, percepção rítmica, leitura musical, prática instrumental, coral, história da música, desenho, pintura, teatro e fotografia -- incluindo música sacra e congregacional como uma trilha entre várias, não a única.","starterObjectives":["Desenvolver percepção rítmica e leitura musical básica em um instrumento ou na voz","Realizar uma apresentação artística ou musical registrada em portfólio"]},{"name":"Ofícios Práticos","color":"#CA8A04","icon":"scissors","description":"Marcenaria, culinária, costura, jardinagem, elétrica básica, manutenção residencial e artesanato -- formação para o trabalho, o serviço e a responsabilidade cotidiana.","starterObjectives":["Concluir um projeto artesanal ou de marcenaria funcional do início ao fim","Preparar uma refeição completa com segurança alimentar e organização de cozinha"]},{"name":"Tecnologia e Criação","color":"#2563EB","icon":"compass","description":"Programação, eletrônica, robótica, impressão 3D, fabricação digital e produção audiovisual -- criar e resolver problemas com ferramentas do nosso tempo.","starterObjectives":["Construir um projeto simples de programação ou eletrônica funcional","Produzir um material audiovisual ou digital documentando um processo de aprendizagem"]},{"name":"Vocação e Serviço","color":"#0D9488","icon":"hand-heart","description":"Empreendedorismo, projetos comunitários, mentoria profissional e serviço cristão -- vocação como chamado, não apenas escolha de carreira.","starterObjectives":["Planejar e executar um pequeno projeto empreendedor ou comunitário","Participar de uma atividade de serviço com reflexão registrada em portfólio"]},{"name":"Fundamentos da Fé Cristã","color":"#7C3AED","icon":"hand-heart","description":"Narrativa bíblica, doutrinas centrais, oração, vida da igreja e ética cristã aplicada ao cotidiano -- a base comum antes de qualquer aprofundamento denominacional.","starterObjectives":["Recontar os grandes marcos da narrativa bíblica em ordem cronológica","Manter um hábito regular de oração e leitura devocional registrado em diário"]},{"name":"Estudo das Escrituras","color":"#9333EA","icon":"book-open","description":"Leitura bíblica contextualizada, panorama do Antigo e Novo Testamento e introdução a como interpretar um texto com responsabilidade -- distinguindo o que o texto diz do que uma tradição específica interpreta.","starterObjectives":["Elaborar um panorama pessoal dos livros do Antigo e Novo Testamento","Praticar leitura contextualizada de uma passagem, identificando gênero literário e contexto histórico"]},{"name":"Casa, Culinária e Cultivo","color":"#16A34A","icon":"sprout","description":"Segurança alimentar, preparo de refeições, panificação, orçamento doméstico e horta caseira -- da cozinha ao cultivo, mordomia prática do lar.","starterObjectives":["Planejar e preparar um cardápio semanal simples dentro de um orçamento definido","Manter uma horta doméstica simples do plantio à colheita"]},{"name":"Primeiros Socorros e Resiliência","color":"#DC2626","icon":"shield-check","description":"Primeiros socorros, orientação básica ao ar livre e preparo familiar para emergências -- preservar a vida, prevenir riscos e ajudar outras pessoas, sem confronto ou sobrevivencialismo extremo.","starterObjectives":["Demonstrar procedimentos básicos de primeiros socorros para situações comuns do dia a dia","Montar, com a família, um plano simples de preparo para emergências domésticas"]}]}'::jsonb, CURRENT_TIMESTAMP)
ON CONFLICT ("code", "version") DO NOTHING;

INSERT INTO "pedagogical_model_definitions"
  ("id", "code", "version", "status", "schema_version", "name", "description", "metadata", "published_at")
VALUES (gen_random_uuid(), 'ECLECTIC', 1, 'PUBLISHED', '1.0.0',
  'Eclético', 'Combinação livre de abordagens e métodos, ajustada ao que melhor funciona para o aluno.',
  '{"subjects":[{"name":"Língua Portuguesa","color":"#2563EB","icon":"book-open","description":"Leitura, escrita e gramática combinando métodos conforme o que melhor funciona para o aluno.","starterObjectives":["Desenvolver leitura fluente e interpretação de textos de complexidade adequada","Produzir textos escritos com estrutura clara, usando o método mais eficaz para o aluno"]},{"name":"Matemática","color":"#059669","icon":"calculator","description":"Combinação livre de abordagens concretas, lógicas e aplicadas, ajustada ao ritmo do aluno.","starterObjectives":["Executar operações aritméticas básicas com exatidão","Resolver problemas aplicados escolhendo a abordagem mais adequada ao conceito"]},{"name":"Estudo Temático Flexível","color":"#7C3AED","icon":"layers","description":"Temas de história, geografia e cultura explorados de forma livre, misturando unit studies, livros vivos e material tradicional.","starterObjectives":["Explorar um tema histórico ou geográfico combinando ao menos duas fontes de metodologia diferentes","Produzir um registro do tema estudado no formato mais adequado ao aluno (texto, projeto ou apresentação)"]},{"name":"Ciências & Natureza","color":"#0D9488","icon":"microscope","description":"Observação da natureza, experimentos e leitura científica combinados conforme o interesse e o momento.","starterObjectives":["Realizar uma observação de natureza ou experimento científico simples","Registrar uma descoberta científica no formato que melhor comunique o aprendizado"]},{"name":"Artes & Expressão","color":"#DB2777","icon":"palette","description":"Desenho, pintura, música e expressão criativa livre, sem amarrar-se a um único método.","starterObjectives":["Concluir uma produção artística livre no meio de preferência do aluno","Apreciar e comentar uma obra de arte ou peça musical à escolha"]},{"name":"Musicalização e Artes","color":"#DB2777","icon":"palette","description":"Canto, percepção rítmica, leitura musical, prática instrumental, coral, história da música, desenho, pintura, teatro e fotografia -- incluindo música sacra e congregacional como uma trilha entre várias, não a única.","starterObjectives":["Desenvolver percepção rítmica e leitura musical básica em um instrumento ou na voz","Realizar uma apresentação artística ou musical registrada em portfólio"]},{"name":"Ofícios Práticos","color":"#CA8A04","icon":"scissors","description":"Marcenaria, culinária, costura, jardinagem, elétrica básica, manutenção residencial e artesanato -- formação para o trabalho, o serviço e a responsabilidade cotidiana.","starterObjectives":["Concluir um projeto artesanal ou de marcenaria funcional do início ao fim","Preparar uma refeição completa com segurança alimentar e organização de cozinha"]},{"name":"Tecnologia e Criação","color":"#2563EB","icon":"compass","description":"Programação, eletrônica, robótica, impressão 3D, fabricação digital e produção audiovisual -- criar e resolver problemas com ferramentas do nosso tempo.","starterObjectives":["Construir um projeto simples de programação ou eletrônica funcional","Produzir um material audiovisual ou digital documentando um processo de aprendizagem"]},{"name":"Vocação e Serviço","color":"#0D9488","icon":"hand-heart","description":"Empreendedorismo, projetos comunitários, mentoria profissional e serviço cristão -- vocação como chamado, não apenas escolha de carreira.","starterObjectives":["Planejar e executar um pequeno projeto empreendedor ou comunitário","Participar de uma atividade de serviço com reflexão registrada em portfólio"]},{"name":"Fundamentos da Fé Cristã","color":"#7C3AED","icon":"hand-heart","description":"Narrativa bíblica, doutrinas centrais, oração, vida da igreja e ética cristã aplicada ao cotidiano -- a base comum antes de qualquer aprofundamento denominacional.","starterObjectives":["Recontar os grandes marcos da narrativa bíblica em ordem cronológica","Manter um hábito regular de oração e leitura devocional registrado em diário"]},{"name":"Estudo das Escrituras","color":"#9333EA","icon":"book-open","description":"Leitura bíblica contextualizada, panorama do Antigo e Novo Testamento e introdução a como interpretar um texto com responsabilidade -- distinguindo o que o texto diz do que uma tradição específica interpreta.","starterObjectives":["Elaborar um panorama pessoal dos livros do Antigo e Novo Testamento","Praticar leitura contextualizada de uma passagem, identificando gênero literário e contexto histórico"]},{"name":"Casa, Culinária e Cultivo","color":"#16A34A","icon":"sprout","description":"Segurança alimentar, preparo de refeições, panificação, orçamento doméstico e horta caseira -- da cozinha ao cultivo, mordomia prática do lar.","starterObjectives":["Planejar e preparar um cardápio semanal simples dentro de um orçamento definido","Manter uma horta doméstica simples do plantio à colheita"]},{"name":"Primeiros Socorros e Resiliência","color":"#DC2626","icon":"shield-check","description":"Primeiros socorros, orientação básica ao ar livre e preparo familiar para emergências -- preservar a vida, prevenir riscos e ajudar outras pessoas, sem confronto ou sobrevivencialismo extremo.","starterObjectives":["Demonstrar procedimentos básicos de primeiros socorros para situações comuns do dia a dia","Montar, com a família, um plano simples de preparo para emergências domésticas"]}]}'::jsonb, CURRENT_TIMESTAMP)
